    {
      "name": "MvPolynomial.eval₂_monomial",
      "type": " {R : Type u} {S₁ : Type v} {σ : Type u_1} {a : R} {s : σ →₀ ℕ} [CommSemiring R] [CommSemiring S₁] (f : R →+* S₁) (g : σ → S₁) : MvPolynomial.eval₂ f g ((MvPolynomial.monomial s) a) = f a * s.prod fun n e => g n ^ e",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    },
    {
      "name": "MvPolynomial.eval₂_mul_monomial",
      "type": " {R : Type u} {S₁ : Type v} {σ : Type u_1} [CommSemiring R] [CommSemiring S₁] {p : MvPolynomial σ R} (f : R →+* S₁) (g : σ → S₁) {s : σ →₀ ℕ} {a : R} : MvPolynomial.eval₂ f g (p * (MvPolynomial.monomial s) a) = MvPolynomial.eval₂ f g p * f a * s.prod fun n e => g n ^ e",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    }
  ]
}

